icons={"Home":'<path d="m3 11 9-8 9 8v10H4V11"/><path d="M9 21v-8h6v8"/>',"ChatGPT":'<rect x="3" y="4" width="18" height="14" rx="4"/><path d="m7 18-2 4 6-4"/>',"Activity":'<path d="M3 12h4l3-8 4 16 3-8h4"/>',"Setup":'<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',"Settings":'<circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r="9"/>'}
def icon(n):return '<svg viewBox="0 0 24 24">'+icons[n]+'</svg>'
def button(text,id,kind='primary',disabled=False):return f'<button id="{id}" class="{kind}" '+('disabled' if disabled else '')+f'>{text}</button>'
def gate(title,text,success=False):return f'<div class="setup-result" data-result-state="{"success" if success else "missing"}"><strong>{title}</strong><p>{text}</p></div>'
def foot(enabled=False):return '<footer class="setup-wizard-footer">'+button('Back','back','text-button')+button('Continue','continue','primary',not enabled)+'</footer>'
def nav(page,signready=False):
 return '<ol class="setup-progress">'+''.join(f'<li><button class="setup-progress-step" '+('aria-current="step" ' if p==page else '')+f'id="step-{p}">{"✓" if i==1 and signready and p!=page else str(i) if i else ""} {t}</button></li>' for i,(p,t) in enumerate([('overview','Overview'),('signin','Sign in'),('folders','Workspaces'),('connection','Connect this Mac'),('attachment','Add to ChatGPT')]))+'</ol>'
def main(page,content,signready=False):
 title={'overview':'Welcome to Farol','signin':'Sign in to ChatGPT','folders':'Choose workspaces','connection':'Connect this Mac'}[page]
 desc={'overview':'Let ChatGPT work with workspaces on this Mac. Setup takes about five minutes, and every step checks itself.','signin':'Use your own ChatGPT account. Farol checks sign-in before you continue.','folders':'Farol enforces the workspace access you approve here. ChatGPT manages action confirmations.','connection':'You need two things from OpenAI: a tunnel ID and its key.'}[page]
 return '<div class="setup-wizard">'+nav(page,signready)+f'<header class="setup-wizard-intro"><h1>{title}</h1><p class="description">{desc}</p></header>'+content+'</div>'
def workspace(mode='empty',access='read',commands=False,menu=False):
 checking=mode=='checking';ready=mode=='ready';empty=mode=='empty'
 content='<div class="setup-workspaces">'
 if not empty:
  content+='<article class="setup-workspace-row"><div class="workspace-row-path"><strong>Farol Demo</strong><p class="description">/Users/demo/Documents/Farol Demo</p></div>'
  content+='<label class="access-wrap">Access <select id="access"'+(' disabled' if checking else '')+'><option>'+('Read only' if access=='read' else 'Read &amp; write')+'</option></select>'
  if menu:content+='<div class="access-menu"><div class="selected">✓ Read only</div><div id="read-write-option">　Read &amp; write</div></div>'
  content+='</label><label class="workspace-commands"><input id="commands" type="checkbox" '+('checked ' if commands else '')+('disabled ' if checking else '')+'>Commands</label>'
  content+='<div class="workspace-row-result">'+('<span class="setup-success">✓ Works</span>' if ready else '<span>Workspace access has not passed its check.</span>'+button('Check access','checkaccess','text-button',True))+'</div>'+button('Remove Farol Demo','remove','text-button',checking)+'</article>'
 content+='</div>'+button('Checking workspace…' if checking else '+ Add workspace','add','primary' if empty else 'subtle',checking)
 content+='<p class="description">Commands lets ChatGPT run Git, tests and builds in approved workspaces, including Git history, hooks and your Git configuration. ChatGPT manages action confirmations; Farol enforces your approved access. Command access is shared by all workspaces.</p>'
 if empty:content+='<p class="description">Add a workspace to continue.</p>'
 if ready:content+=gate('Ready to continue','All listed workspaces passed their access checks. You can continue.',True)
 elif checking:content+=gate('Checking…','Wait for the current workspace access check to finish.')
 else:content+=gate('Your next step','Add at least one workspace and check its access to continue.')
 return main('folders',content+foot(ready),True)
def picker(selected=False):
 return '''<div class="shade"><div class="picker"><div class="picker-head"><span>‹　›</span><div class="picker-location">Documents　⌄</div><span>⌕ Search</span></div><div class="picker-body"><div class="picker-side"><strong>Favorites</strong><div>Desktop</div><div class="current">Documents</div><div>Downloads</div></div><div class="picker-list"><div class="cols"><span>Name</span><span>Kind</span></div><div id="sample-folder" class="folder-entry '''+('selected' if selected else '')+'''"><i class="folder-icon"></i><span>Farol Demo</span><span style="margin-left:auto;font-size:11px;opacity:.65">Folder</span></div></div></div><div class="picker-foot">'''+button('Cancel','cancel','subtle')+button('Open','openfolder','primary',not selected)+'''</div></div></div>'''
def auth(which):
 if which=='auth':return '<div class="authpage"><span class="samplebadge">ILLUSTRATIVE SIGN-IN</span><div class="authcard"><h1>Log in or sign up</h1><p>Welcome back to ChatGPT</p>'+button('<b>G</b> Continue with Google','google','google')+button('Continue with Apple','apple','social')+button('Continue with Microsoft','microsoft','social')+'<div class="or">OR</div><div class="login-email">Email address</div>'+button('Continue','email','continue')+'</div><div class="provider-note">Sign-in options and screens may vary by account.</div></div>'
 if which=='google':return '<div class="authpage"><span class="samplebadge">SAMPLE ACCOUNT</span><div class="account-card"><div class="g">G</div><h1>Choose an account</h1><p>to continue to OpenAI</p>'+button('<span class="avatar">D</span><span><strong>Demo User</strong><small>demo@example.com</small></span>','account','account')+'<p style="font-size:11px;margin-top:22px">Illustration only. Use your own account when signing in.</p></div></div>'
 return '<div class="chat-ready"><span class="samplebadge">SAMPLE ACCOUNT</span><h1>What can I help with?</h1><div class="composer">Ask anything<div><span>＋　Tools</span><span>◉</span></div></div><div class="returnhelp">Signed in. Return to Setup to check your sign-in.</div></div>'
def shell(content,page='signin',chat=False,overlay=''):
 rail=''.join(f'<button '+('aria-current="page"' if n==('ChatGPT' if chat else 'Setup') else '')+'>'+icon(n)+n+'</button>' for n in ['Home','ChatGPT','Activity','Setup'])
 toolbar=f'<div class="navigation-chrome"><div class="traffic-light-space"><i></i><i></i><i></i></div><span style="color:#999">‹　›　◫</span></div><div class="toolbar-title"><strong>{"ChatGPT" if chat else "Setup"}</strong><span>/</span><span>{"Sign in" if chat else {"signin":"Sign in","overview":"Overview","folders":"Workspaces","connection":"Connect this Mac"}[page]}</span></div>'
 if chat:toolbar+='<div class="sign-in-context"><span>Setup · Sign in</span>'+button('←　Back to setup','return','connection-check-return')+'</div>'
 else:toolbar+='<button class="search-trigger">⌕　Find a page <kbd>⌘ K</kbd></button>'
 return '<div class="window"><div class="desktop" data-theme="light"><header class="toolbar">'+toolbar+'</header><aside class="rail">'+rail+'<div class="rail-footer"><small>○　Not connected</small><button>'+icon('Settings')+'Settings</button></div></aside><main class="stage">'+content+'</main></div>'+overlay+'</div>'
scenes=[]
def add(name,part,step,caption,content,page='signin',chat=False,overlay='',note='UI recreation · Synthetic data · Not a live setup test'):
 title={'signin':'1. Sign in to ChatGPT','workspace':'2. Add a workspace','access':'Optional: enable edits and commands'}[part]
 html='<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="shell.css"><link rel="stylesheet" href="setup.css"><link rel="stylesheet" href="demo.css"></head><body><div class="story"><div class="brand"><small>STEP-BY-STEP SETUP</small></div><div class="heading"><h1>'+title+'</h1><span>Follow the cursor</span></div>'+shell(content,page,chat,overlay)+f'<div class="caption"><b>{step}</b>{caption}</div><div class="footer"><span>{note}</span><span>Farol · November 2026</span></div></div></body></html>'
 (R/(name+'.html')).write_text(html);scenes.append(name)
overview='<section class="setup-welcome"><div class="setup-overview-summary"><strong>0 of 4 steps ready</strong><p class="description">Follow the steps below. Your progress is saved as you go.</p></div><ol>'
for i,(name,desc) in enumerate([('Sign in','Sign in with your ChatGPT account'),('Workspaces','Choose folders for ChatGPT'),('Connect this Mac','Connect this Mac with your tunnel'),('Add to ChatGPT','Add your app and confirm the connection')]):overview+=f'<li><button class="setup-overview-step"><span class="setup-overview-marker">{i+1}</span><span class="setup-overview-copy"><strong>{name}</strong><span class="description">{desc}</span></span><span class="setup-overview-state">Set up</span></button></li>'
overview+='</ol>'+button('Start setup','start')+'</section>'
add('s00','signin',1,'Open Setup and choose Start setup.',main('overview',overview),'overview')
add('s01','signin',2,'Choose Sign in. Farol opens its ChatGPT tab.',main('signin','<p class="description">Sign in to your ChatGPT account, then return here.</p><p style="margin-top:15px">'+button('Sign in','signin')+'</p>'+gate('Your next step','Sign in to ChatGPT, then return to Setup.')+foot()))
add('s02','signin',3,'Choose your usual sign-in method. Google is shown here.',auth('auth'),chat=True,note='UI recreation · Illustrative sign-in screens · Synthetic data')
add('s03','signin',3,'Use your own account. This example contains no real login details.',auth('google'),chat=True,note='UI recreation · Illustrative sign-in screens · Synthetic data')
add('s04','signin',4,'After signing in, choose Back to setup.',auth('ready'),chat=True)
add('s05','signin',5,'Choose Check sign-in once, then wait for the result.',main('signin','<p class="description">You’re signed in. Check sign-in to continue.</p><p style="margin-top:15px">'+button('Check sign-in','checksignin')+'</p>'+gate('Your next step','Sign-in needs a fresh check in this window. Choose Check sign-in to continue.')+foot()))
add('s06','signin',5,'Farol checks sign-in. Wait for the confirmation.',main('signin','<p class="description">Checking sign-in…</p><p style="margin-top:15px">'+button('Check sign-in','checksignin','primary',True)+'</p>'+gate('Checking…','Wait for the current sign-in check to finish.')+foot()))
add('s07','signin',6,'When Sign-in checked appears, choose Continue.',main('signin',gate('✓ Sign-in checked','Your ChatGPT sign-in is confirmed. Continue to choose workspaces.',True)+foot(True)))
add('s08','signin',6,'Sign-in is checked. Next, choose a workspace.',workspace(),'folders')
add('w00','workspace',1,'Choose + Add workspace.',workspace(),'folders')
add('w01','workspace',2,'Select a small folder with non-sensitive sample files.',workspace(),'folders',overlay=picker())
add('w02','workspace',2,'Choose Open to add the selected folder.',workspace(),'folders',overlay=picker(True))
add('w03','workspace',3,'New workspaces start with Read only. Farol checks access.',workspace('checking'),'folders')
add('w04','workspace',4,'Wait for Works. Read only leaves files unchanged.',workspace('ready'),'folders')
add('w05','workspace',5,'Choose Continue after every listed workspace says Works.',workspace('ready'),'folders')
add('w06','workspace',5,'Workspace access is checked. Next, connect this Mac.',main('connection','<h3>1. Create a tunnel and a key</h3><p class="description" style="margin:12px 0 20px">Create a tunnel in OpenAI, then copy its tunnel ID and restricted key into Farol.</p>'+button('Open OpenAI Tunnels','tunnels','text-button')+gate('Your next step','Connect this Mac with your tunnel to continue.')+foot(),True),'connection')
add('a00','access',1,'Keep Read only unless you need ChatGPT to edit files.',workspace('ready'),'folders')
add('a01','access',2,'For approved file edits, choose Read & write.',workspace('ready',menu=True),'folders')
add('a02','access',2,'Farol saves the change and checks workspace access.',workspace('checking',access='write'),'folders')
add('a03','access',3,'Wait for Works before using the new access.',workspace('ready',access='write'),'folders')
add('a04','access',4,'Enable Commands only if you need Git, tests or builds.',workspace('ready',access='write'),'folders')
add('a05','access',4,'Command access applies to all approved workspaces.',workspace('checking',access='write',commands=True),'folders')
add('a06','access',5,'Works confirms the check. ChatGPT still manages action approvals.',workspace('ready',access='write',commands=True),'folders')
(R/'scenes.json').write_text(json.dumps(scenes))
print(len(scenes),'screens generated')
